  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['onboarding_version'] = Variable<int>(onboardingVersion);
    if (!nullToAbsent || wifiMaxBitRate != null) {
      map['wifi_max_bit_rate'] = Variable<int>(wifiMaxBitRate);
    }
    if (!nullToAbsent || wifiFormat != null) {
      map['wifi_format'] = Variable<String>(wifiFormat);
    }
    if (!nullToAbsent || cellularMaxBitRate != null) {
      map['cellular_max_bit_rate'] = Variable<int>(cellularMaxBitRate);
    }
    if (!nullToAbsent || cellularFormat != null) {
      map['cellular_format'] = Variable<String>(cellularFormat);
    }
    map['cached_playback_first'] = Variable<bool>(cachedPlaybackFirst);
    map['scrobble_enabled'] = Variable<bool>(scrobbleEnabled);
    map['gapless_enabled'] = Variable<bool>(gaplessEnabled);
    map['skip_silence_enabled'] = Variable<bool>(skipSilenceEnabled);
    map['show_albums_page'] = Variable<bool>(showAlbumsPage);
    map['show_radio_page'] = Variable<bool>(showRadioPage);
    map['show_playlists_page'] = Variable<bool>(showPlaylistsPage);
    map['show_artists_page'] = Variable<bool>(showArtistsPage);
    map['show_liked_page'] = Variable<bool>(showLikedPage);
    map['rolling_cache_budget_mb'] = Variable<int>(rollingCacheBudgetMb);
    map['wifi_only_downloads'] = Variable<bool>(wifiOnlyDownloads);
    map['auto_download_starred_on_wifi'] = Variable<bool>(
      autoDownloadStarredOnWifi,
    );
    map['custom_download_folder_enabled'] = Variable<bool>(
      customDownloadFolderEnabled,
    );
    if (!nullToAbsent || customDownloadFolderPath != null) {
      map['custom_download_folder_path'] = Variable<String>(
        customDownloadFolderPath,
      );
    }
    map['custom_download_folder_storage_kind'] = Variable<String>(
      customDownloadFolderStorageKind,
    );
    map['download_quality_mode'] = Variable<String>(downloadQualityMode);
    map['download_max_bit_rate'] = Variable<int>(downloadMaxBitRate);
    map['download_format'] = Variable<String>(downloadFormat);
    map['download_quality_prompted'] = Variable<bool>(downloadQualityPrompted);
    map['max_concurrent_downloads'] = Variable<int>(maxConcurrentDownloads);
    map['downloads_paused'] = Variable<bool>(downloadsPaused);
    map['theme_mode'] = Variable<String>(themeMode);
    map['color_style'] = Variable<String>(colorStyle);
    map['oled_for_auto'] = Variable<bool>(oledForAuto);
    map['night_schedule_enabled'] = Variable<bool>(nightScheduleEnabled);
    map['night_schedule_start_minutes'] = Variable<int>(
      nightScheduleStartMinutes,
    );
    map['night_schedule_end_minutes'] = Variable<int>(nightScheduleEndMinutes);
    map['flat_surfaces'] = Variable<bool>(flatSurfaces);
    map['color_vividness'] = Variable<int>(colorVividness);
    map['surface_depth_light'] = Variable<int>(surfaceDepthLight);
    map['surface_depth_dark'] = Variable<int>(surfaceDepthDark);
    map['color_tuning_presets'] = Variable<String>(colorTuningPresets);
    if (!nullToAbsent || selectedColorTuningPresetId != null) {
      map['selected_color_tuning_preset_id'] = Variable<String>(
        selectedColorTuningPresetId,
      );
    }
    map['appearance_looks'] = Variable<String>(appearanceLooks);
    if (!nullToAbsent || selectedAppearanceLookId != null) {
      map['selected_appearance_look_id'] = Variable<String>(
        selectedAppearanceLookId,
      );
    }
    map['flat_areas'] = Variable<int>(flatAreas);
    map['album_art_shade'] = Variable<bool>(albumArtShade);
    map['album_art_colored_shade'] = Variable<bool>(albumArtColoredShade);
    if (!nullToAbsent || colorSchemeSeed != null) {
      map['color_scheme_seed'] = Variable<int>(colorSchemeSeed);
    }
    if (!nullToAbsent || customColorPresets != null) {
      map['custom_color_presets'] = Variable<String>(customColorPresets);
    }
    if (!nullToAbsent || appLocale != null) {
      map['app_locale'] = Variable<String>(appLocale);
    }
    map['crossfade_enabled'] = Variable<bool>(crossfadeEnabled);
    map['crossfade_duration_seconds'] = Variable<int>(crossfadeDurationSeconds);
    map['crossfade_type'] = Variable<String>(crossfadeType);
    map['cover_art_cache_max_objects'] = Variable<int>(coverArtCacheMaxObjects);
    map['art_tinted_now_playing'] = Variable<bool>(artTintedNowPlaying);
    map['corner_style'] = Variable<String>(cornerStyle);
    map['now_playing_background'] = Variable<String>(nowPlayingBackground);
    map['dynamic_album_color_enabled'] = Variable<bool>(
      dynamicAlbumColorEnabled,
